<script setup>
import {onMounted,ref} from 'vue';
const props=defineProps({indexUrl:String,createUrl:String,csrf:String,success:String,error:String});
const rows=ref([]),loading=ref(true),creating=ref(false),loadError=ref('');
async function load(){loading.value=true;try{const r=await fetch(props.indexUrl,{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await r.json();if(!r.ok)throw new Error(d.message||'Could not load backups');rows.value=d.backups||[]}catch(e){loadError.value=e.message}finally{loading.value=false}}
function size(bytes){if(bytes<1024)return bytes+' B';if(bytes<1048576)return (bytes/1024).toFixed(1)+' KB';return (bytes/1048576).toFixed(2)+' MB'}
async function confirmAction(row,kind,event){event.preventDefault();const form=event.currentTarget;const restore=kind==='restore';let ok=false;if(window.Swal){const result=await window.Swal.fire({title:restore?'Restore Database?':'Delete Backup?',html:restore?`<p>You are about to restore <strong>${row.name}</strong>.</p><p>The current database will be replaced with the data stored in this backup.</p><p><strong>This action should only be performed when you are sure.</strong></p>`:`<p>Are you sure you want to delete <strong>${row.name}</strong>?</p><p>This backup file will be permanently deleted.</p>`,icon:'warning',showCancelButton:true,confirmButtonText:restore?'Yes, Restore':'Yes, Delete',cancelButtonText:'Cancel',reverseButtons:true,focusCancel:true,buttonsStyling:false,customClass:{confirmButton:restore?'btn btn-primary':'btn btn-danger',cancelButton:'btn btn-secondary'}});ok=result.isConfirmed}else ok=confirm(restore?'Restore database from '+row.name+'? This replaces current database data.':'Permanently delete '+row.name+'?');if(ok){if(restore){const button=form.querySelector('button[type=submit]');if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm" aria-hidden="true"></span>'}}form.submit()}}
function startCreate(event){creating.value=true;const button=event.currentTarget.querySelector('button[type=submit]');if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm" aria-hidden="true"></span><span>Creating Backup...</span>'}}
onMounted(load);
</script>
<template><div class="dashboard-section backup-page">
<div class="dashboard-panel backup-header-panel"><div class="backup-header-content"><div class="backup-header-text"><span class="backup-eyebrow"><i class="bi bi-shield-check"></i> System Protection</span><h1 class="backup-page-title">System Backup</h1><p class="backup-page-description">Create and manage secure database backups of your SecondBook system.</p></div><div class="backup-header-action"><form :action="createUrl" method="POST" @submit="startCreate"><input type="hidden" name="_token" :value="csrf"><button type="submit" class="btn backup-create-btn" :disabled="creating"><i class="bi bi-cloud-arrow-up"></i><span>Create Backup</span></button></form></div></div></div>
<div v-if="success" class="alert alert-success backup-alert"><i class="bi bi-check-circle-fill"></i><span>{{success}}</span></div><div v-if="error||loadError" class="alert alert-danger backup-alert"><i class="bi bi-exclamation-triangle-fill"></i><span>{{error||loadError}}</span><button v-if="loadError" class="btn btn-sm btn-light ms-auto" @click="load">Retry</button></div>
<div class="row g-4 backup-stats-row"><div class="col-xl-4 col-md-6"><div class="dashboard-panel backup-stat-card"><div class="backup-stat-icon protection"><i class="bi bi-shield-lock"></i></div><div class="backup-stat-content"><span class="backup-stat-label">Backup Protection</span><h3>Active</h3><p>Your database backup system is ready.</p></div></div></div><div class="col-xl-4 col-md-6"><div class="dashboard-panel backup-stat-card"><div class="backup-stat-icon backups"><i class="bi bi-database-check"></i></div><div class="backup-stat-content"><span class="backup-stat-label">Total Backups</span><h3>{{rows.length}}</h3><p>Backup archives currently stored.</p></div></div></div><div class="col-xl-4 col-md-12"><div class="dashboard-panel backup-stat-card"><div class="backup-stat-icon latest"><i class="bi bi-clock-history"></i></div><div class="backup-stat-content"><span class="backup-stat-label">Last Backup</span><h3>{{rows[0]?.modified_at||'Never'}}</h3><p>Most recently created backup.</p></div></div></div></div>
<div class="dashboard-panel backup-history-panel"><div class="backup-history-header"><div><span class="backup-section-eyebrow">Backup Storage</span><h2 class="backup-section-title">Backup History</h2><p class="backup-section-description">View, download and manage your existing backup archives.</p></div><div class="backup-history-count"><i class="bi bi-archive"></i> {{rows.length}} Backups</div></div>
<div v-if="loading" class="text-center py-5">Loading backup archives…</div><div v-else-if="rows.length" class="table-responsive backup-table-wrapper"><table class="table backup-table align-middle"><thead><tr><th>Backup File</th><th>Type</th><th>Size</th><th>Date Created</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.name"><td><div class="backup-file-cell"><div class="backup-file-icon"><i class="bi bi-file-earmark-zip"></i></div><div class="backup-file-info"><span class="backup-file-name">{{row.name}}</span></div></div></td><td><span class="backup-type-badge"><i class="bi bi-database"></i> Database</span></td><td><span class="backup-size">{{size(row.size)}}</span></td><td><div class="backup-date">{{row.modified_at}}</div></td><td><div class="backup-actions"><a :href="row.download_url" class="backup-action-btn download" title="Download"><i class="bi bi-download"></i></a><form :action="row.restore_url" method="POST" class="backup-action-form restore-backup-form" :data-file="row.name" @submit="confirmAction(row,'restore',$event)"><input type="hidden" name="_token" :value="csrf"><button class="backup-action-btn restore" title="Restore" type="submit"><i class="bi bi-arrow-counterclockwise"></i></button></form><form :action="row.delete_url" method="POST" class="backup-action-form delete-backup-form" :data-file="row.name" @submit="confirmAction(row,'delete',$event)"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button class="backup-action-btn delete" title="Delete" type="submit"><i class="bi bi-trash3"></i></button></form></div></td></tr></tbody></table></div><div v-else class="backup-empty-state"><div class="backup-empty-icon"><i class="bi bi-database-x"></i></div><h3>No Backups Yet</h3><p>Create a backup to protect your database.</p><form :action="createUrl" method="POST" @submit="startCreate"><input type="hidden" name="_token" :value="csrf"><button type="submit" class="btn backup-empty-btn" :disabled="creating"><i class="bi bi-cloud-arrow-up"></i> Create First Backup</button></form></div></div></div></template>
